        border-radius: 32px;
        background: var(--panel);
        backdrop-filter: blur(18px);
        box-shadow: var(--shadow);
      }

      .hero {
        display: grid;
        gap: 14px;
        margin-bottom: 28px;
      }

      .eyebrow {
        width: fit-content;
        padding: 8px 12px;
        border-radius: 999px;
        font-size: 0.8rem;
        font-weight: 700;
        letter-spacing: 0.04em;
        text-transform: uppercase;
        color: var(--accent);
        background: var(--accent-soft);
      }

      h1 {
        margin: 0;
        font-size: clamp(2.2rem, 5vw, 4rem);
        line-height: 1.02;
        letter-spacing: -0.04em;
      }

      .lede {
        max-width: 720px;
        margin: 0;
        font-size: 1.05rem;
        line-height: 1.7;
        color: var(--muted);
      }

      .faq-list {
        display: grid;
        gap: 16px;
      }

      .example {
        border: 1px solid var(--line);
        border-radius: var(--radius);
        background: var(--panel-solid);
        overflow: clip;
        transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
      }

      .example:hover {
        transform: translateY(-1px);
        box-shadow: 0 18px 36px rgba(34, 53, 91, 0.08);
        border-color: rgba(91, 124, 255, 0.2);
      }

      .trigger {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        width: 100%;
        padding: 22px 24px;
        border: 0;
        background: transparent;
        color: inherit;
        text-align: left;
        cursor: pointer;
        font: inherit;
