      const faqItems = [
        {
          question: "Why do cats purr?",
          answer:
            "Cats usually purr when they feel safe, content, or connected, but they can also purr to comfort themselves when stressed. It is a surprisingly versatile signal that can mean everything from relaxation to a request for attention."
        },
        {
          question: "How much sleep do cats need?",
          answer:
            "Most cats sleep between 12 and 16 hours a day, and some nap even longer. Their bursts of playful energy are balanced by lots of rest, which comes from their natural instinct to conserve energy between hunting-like activity."
        },
        {
          question: "Why do cats knead blankets and laps?",
          answer:
            "Kneading starts in kittenhood when nursing, and many adult cats keep the behavior because it feels soothing and familiar. It is often a sign of comfort, trust, and settling into a favorite spot."
        },
        {
          question: "Do indoor cats still need enrichment?",
          answer:
            "Yes. Indoor cats benefit from climbing spots, scratchers, toys, puzzle feeders, and window views. Enrichment keeps them mentally engaged, helps prevent boredom, and supports healthy exercise."
        },
        {
          question: "Why do cats flick or swish their tails?",
          answer:
            "A cat's tail often reflects its mood. A gentle upright tail can show confidence, while fast flicking may signal irritation, intense focus, or overstimulation. Reading the tail together with ears and posture gives the clearest picture."
        }
      ];

      const state = {
        openIndexes: new Set()
      };

      const createNode = (markup) => {
        const template = document.createElement("template");
        template.innerHTML = markup.trim();
        return template.content.firstElementChild;
      };

      const Hero = () =>
        createNode(`
          <header class="hero">
            <div class="eyebrow">Cat care essentials</div>
            <h1>Frequently asked questions about cats</h1>
            <p class="lede">
              A simple guide to common cat behavior, daily habits, and what your feline friend may be trying to tell you.
            </p>
          </header>
        `);

      const FAQItem = ({ item, index }) => {
        const isOpen = state.openIndexes.has(index);

        return createNode(`
          <div class="example${isOpen ? " is-open" : ""}">
            <button
              class="trigger"
              type="button"
              aria-expanded="${isOpen}"
              aria-controls="faq-panel-${index}"
              data-index="${index}"
            >
              <span class="question">${item.question}</span>
              <span class="icon" aria-hidden="true">+</span>
            </button>
            <div class="details" id="faq-panel-${index}">
              <div class="details-inner">
                <p class="answer">${item.answer}</p>
              </div>
            </div>
          </div>
        `);
      };

      const FAQList = () => {
        const list = createNode('<section class="faq-list" aria-label="Cat frequently asked questions"></section>');
        faqItems.forEach((item, index) => list.appendChild(FAQItem({ item, index })));
        return list;
      };

      const App = () => {
        const app = createNode('<main class="app"></main>');
        app.appendChild(Hero());
        app.appendChild(FAQList());
        return app;
      };

      const render = () => {
        const root = document.getElementById("root");
        root.replaceChildren(App());
      };

      document.addEventListener("click", (event) => {
        const trigger = event.target.closest(".trigger");
        if (!trigger) return;

        const index = Number(trigger.dataset.index);
        if (state.openIndexes.has(index)) {
          state.openIndexes.delete(index);
        } else {
          state.openIndexes.add(index);
        }

        render();
      });

      render();
    </script>
  </body>
</html>
