 <!DOCTYPE html>
 <html lang="en">
   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Cat FAQ</title>
     <style>
       :root {
         --bg: #f4f7fb;
         --panel: rgba(255, 255, 255, 0.82);
         --panel-solid: #ffffff;
         --text: #132238;
         --muted: #5f7188;
         --line: rgba(19, 34, 56, 0.08);
         --accent: #5b7cff;
         --accent-soft: rgba(91, 124, 255, 0.12);
         --shadow: 0 24px 60px rgba(34, 53, 91, 0.12);
         --radius: 24px;
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         background:
           radial-gradient(circle at top left, rgba(91, 124, 255, 0.2), transparent 30%),
           radial-gradient(circle at top right, rgba(26, 193, 255, 0.14), transparent 28%),
           var(--bg);
         color: var(--text);
       }

       .shell {
         min-height: 100vh;
         padding: 48px 20px;
       }

       .app {
         width: min(960px, 100%);
         margin: 0 auto;
         padding: 40px;
         border: 1px solid rgba(255, 255, 255, 0.7);
         border-radius: 32px;
         background: var(--panel);
         backdrop-filter: blur(18px);
         box-shadow: var(--shadow);
       }

       .hero {
         display: grid;
         gap: 14px;
         margin-bottom: 28px;
       }

       .eyebrow {
         width: fit-content;
         padding: 8px 12px;
         border-radius: 999px;
         font-size: 0.8rem;
         font-weight: 700;
         letter-spacing: 0.04em;
         text-transform: uppercase;
         color: var(--accent);
         background: var(--accent-soft);
       }

       h1 {
         margin: 0;
         font-size: clamp(2.2rem, 5vw, 4rem);
         line-height: 1.02;
         letter-spacing: -0.04em;
       }

       .lede {
         max-width: 720px;
         margin: 0;
         font-size: 1.05rem;
         line-height: 1.7;
         color: var(--muted);
       }

       .faq-list {
         display: grid;
         gap: 16px;
       }

       .example {
         border: 1px solid var(--line);
         border-radius: var(--radius);
         background: var(--panel-solid);
         overflow: clip;
         transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
       }

       .example:hover {
         transform: translateY(-1px);
         box-shadow: 0 18px 36px rgba(34, 53, 91, 0.08);
         border-color: rgba(91, 124, 255, 0.2);
       }

       .trigger {
         display: flex;
         align-items: center;
         justify-content: space-between;
         gap: 16px;
         width: 100%;
         padding: 22px 24px;
         border: 0;
         background: transparent;
         color: inherit;
         text-align: left;
         cursor: pointer;
         font: inherit;
       }

       .trigger:focus-visible {
         outline: 3px solid rgba(91, 124, 255, 0.28);
         outline-offset: -3px;
       }

       .question {
         font-size: 1.05rem;
         font-weight: 700;
         line-height: 1.4;
       }

       .icon {
         flex: 0 0 auto;
         display: grid;
         place-items: center;
         width: 36px;
         height: 36px;
         border-radius: 50%;
         background: var(--accent-soft);
         color: var(--accent);
         font-size: 1.35rem;
         font-weight: 500;
         transition: transform 180ms ease, background 180ms ease;
       }

       .example.is-open .icon {
         transform: rotate(45deg);
         background: rgba(91, 124, 255, 0.18);
       }

       .details {
         display: grid;
         grid-template-rows: 0fr;
         transition: grid-template-rows 220ms ease;
       }

       .example.is-open .details {
         grid-template-rows: 1fr;
       }

       .details-inner {
         min-height: 0;
         overflow: hidden;
       }

       .answer {
         margin: 0;
         padding: 0 24px 24px;
         color: var(--muted);
         line-height: 1.75;
       }

       @media (max-width: 640px) {
         .shell {
           padding: 24px 14px;
         }

         .app {
           padding: 24px;
           border-radius: 24px;
         }

         .trigger,
         .answer {
           padding-left: 18px;
           padding-right: 18px;
         }
       }
     </style>
   </head>
   <body>
     <div class="shell">
       <div id="root"></div>
     </div>

     <script>
       const faqItems = [
         {
           question: "Why do cats purr?",
           answer:
             "Cats usually purr when they feel safe, content, or connected, but they can also purr to comfort themselves when stressed. It is a surprisingly versatile signal that can mean everything from relaxation to a request for attention."
         },
         {
           question: "How much sleep do cats need?",
           answer:
             "Most cats sleep between 12 and 16 hours a day, and some nap even longer. Their bursts of playful energy are balanced by lots of rest, which comes from their natural instinct to conserve energy between hunting-like activity."
         },
         {
           question: "Why do cats knead blankets and laps?",
           answer:
             "Kneading starts in kittenhood when nursing, and many adult cats keep the behavior because it feels soothing and familiar. It is often a sign of comfort, trust, and settling into a favorite spot."
         },
         {
           question: "Do indoor cats still need enrichment?",
           answer:
             "Yes. Indoor cats benefit from climbing spots, scratchers, toys, puzzle feeders, and window views. Enrichment keeps them mentally engaged, helps prevent boredom, and supports healthy exercise."
         },
         {
           question: "Why do cats flick or swish their tails?",
           answer:
             "A cat's tail often reflects its mood. A gentle upright tail can show confidence, while fast flicking may signal irritation, intense focus, or overstimulation. Reading the tail together with ears and posture gives the clearest picture."
         }
       ];

       const state = {
         openIndexes: new Set()
       };

       const createNode = (markup) => {
         const template = document.createElement("template");
         template.innerHTML = markup.trim();
         return template.content.firstElementChild;
       };

       const Hero = () =>
         createNode(`
           <header class="hero">
             <div class="eyebrow">Cat care essentials</div>
             <h1>Frequently asked questions about cats</h1>
             <p class="lede">
               A simple guide to common cat behavior, daily habits, and what your feline friend may be trying to tell you.
             </p>
           </header>
         `);

       const FAQItem = ({ item, index }) => {
         const isOpen = state.openIndexes.has(index);

         return createNode(`
           <div class="example${isOpen ? " is-open" : ""}">
             <button
               class="trigger"
               type="button"
               aria-expanded="${isOpen}"
               aria-controls="faq-panel-${index}"
               data-index="${index}"
             >
               <span class="question">${item.question}</span>
               <span class="icon" aria-hidden="true">+</span>
             </button>
             <div class="details" id="faq-panel-${index}">
               <div class="details-inner">
                 <p class="answer">${item.answer}</p>
')
